/// Executes in SUPERVISOR mode ///

void adc_irq_service (void)
{
  AD0INTEN &= ~ ((UInt32) 1 << 8) ;    // Disable global ADC irq

  (& AD0DR0) [adc_channel_selected] ;  // Read result to clear irq flag

  os_irq_set_i (adc_irq_done) ;        // Signal waiting task
}

